files = []
for name, body in sources.items():
    dest = stubs / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(body, encoding='utf-8')
    files.append(str(dest))
files += [str(root / 'src/com/ansub/tvhome' / name) for name in ['GamingVideoBackground.java', 'VideoStartGuard.java']]
subprocess.run([str(args.java_home/'bin/javac.exe'), '-encoding', 'UTF-8', '-d', str(classes), *files], check=True)
subprocess.run([str(args.java_home/'bin/java.exe'), '-cp', str(classes), 'com.ansub.tvhome.GamingVideoRuntime'], check=True)
